using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Benefits;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class BenefitAllocationTests
{
 class User(bool grant):ICurrentUser{public string Email=>"allocation@example.local";public int? EmployeeId=>6;public int UserId=>7;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>grant?p==Perm.BenefitsManage:p is Perm.ReportsFin or Perm.ScopeCompany or Perm.EmpManage;}
 static BenefitService S(AppDbContext d,bool grant=true){var u=new User(grant);var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c));}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();return d;}
 static async Task Seed(AppDbContext d){d.Add(new BenefitPlan{Id=1,Currency="EGP",EmployerMonthly=100,EmployeeMonthly=25});d.Add(new BenefitPlan{Id=2,Currency="USD",EmployerMonthly=10,EmployeeMonthly=2});d.AddRange(new[]{new BenefitEnrollment{Id=1,PlanId=1,EmployeeId=6,CostCenter="OPS",StartsOn=new(2026,12,1),EndsOn=new(2026,12,31)},new BenefitEnrollment{Id=2,PlanId=1,EmployeeId=6,DependentId=1,CostCenter="OPS",StartsOn=new(2026,12,1),EndsOn=new(2026,12,31)},new BenefitEnrollment{Id=3,PlanId=2,EmployeeId=6,CostCenter="OPS",StartsOn=new(2026,12,1),EndsOn=new(2026,12,31)},new BenefitEnrollment{Id=4,PlanId=1,EmployeeId=7,CostCenter="OTHER",StartsOn=new(2026,12,10),EndsOn=new(2026,12,20)}});d.Add(new BenefitCancellation{EnrollmentId=2,EffectiveOn=new(2026,12,15),Reason="Fictional cancellation"});await d.SaveAsync();}
 [Fact]public async Task SnapshotGroupsCurrencyAndCostCentreWithoutProratingOrDoubleCountingEmployees(){await using var d=await Db();await Seed(d);var a=await S(d).AllocationAsync(new(2026,12,14,12,0,0));Assert.Equal(new DateTime(2026,12,14),a.AsOf);Assert.Equal(3,a.Rows.Count);var row=Assert.Single(a.Rows.Where(x=>x.CostCenter=="OPS"&&x.Currency=="EGP"));Assert.Equal(2,row.ActiveEnrollments);Assert.Equal(1,row.Employees);Assert.Equal(200,row.EmployerMonthly);Assert.Equal(50,row.EmployeeMonthly);Assert.Equal(10,a.Rows.Single(x=>x.Currency=="USD").EmployerMonthly);Assert.False(d.ChangeTracker.HasChanges());}
 [Fact]public async Task CancellationStartAndInclusiveEndControlMembership(){await using var d=await Db();await Seed(d);Assert.Empty((await S(d).AllocationAsync(new(2026,11,30))).Rows);Assert.Equal(100,(await S(d).AllocationAsync(new(2026,12,15))).Rows.Single(x=>x.CostCenter=="OPS"&&x.Currency=="EGP").EmployerMonthly);Assert.Contains((await S(d).AllocationAsync(new(2026,12,20))).Rows,x=>x.CostCenter=="OTHER");Assert.DoesNotContain((await S(d).AllocationAsync(new(2026,12,21))).Rows,x=>x.CostCenter=="OTHER");Assert.Equal(2,(await S(d).AllocationAsync(new(2026,12,31))).Rows.Count);Assert.Empty((await S(d).AllocationAsync(new(2027,1,1))).Rows);}
 [Fact]public async Task OwnerCompanyFinanceAndGeneralHrCannotReadAllocationWithoutSeparateGrant(){await using var d=await Db();await Seed(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,false).AllocationAsync(new(2026,12,14)));}
 [Theory][InlineData(1)][InlineData(9999)]public async Task UnsupportedDateRejectedWithoutMutation(int year){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d).AllocationAsync(new(year,1,1)));Assert.False(d.ChangeTracker.HasChanges());}
}
